## Why Asked
This question evaluates understanding of fundamental sorting algorithms and their practical trade-offs in real-world applications.

## Key Concepts
- Divide and conquer strategies
- Partitioning vs merging approaches
- In-place vs auxiliary space requirements
- Algorithm stability and performance characteristics

## Code Example
```
// Quicksort partition
function partition(arr, low, high) {
  const pivot = arr[high];
  let i = low - 1;
  for (let j = low; j < high; j++) {
    if (arr[j] < pivot) {
      i++;
      [arr[i], arr[j]] = [arr[j], arr[i]];
    }
  }
  [arr[i + 1], arr[high]] = [arr[high], arr[i + 1]];
  return i + 1;
}

// Mergesort merge
function merge(left, right) {
  const result = [];
  let i = 0, j = 0;

  while (i < left.length && j < right.length) {
    if (left[i] <= right[j]) {
      result.push(left[i++]);
    } else {
      result.push(right[j++]);
    }
  }

  return result.concat(left.slice(i)).concat(right.slice(j));
}
```

## Why This Is Asked

Tests algorithmic depth and practical handling of worst-case quicksort behavior.

## Key Concepts

- Introsort: hybrid of quicksort and heapsort with depth guard
- Median-of-three pivot to avoid pathological inputs
- In-place partition and recursion depth management
- Complexity: O(n log n) average and worst-case; O(log n) stack space

## Code Example

```javascript
// Introsort skeleton in JS
function introsort(arr) {
  const n = arr.length;
  if (n <= 1) return;
  const maxDepth = Math.floor(2 * Math.log2(n));
  function swap(i, j) { const t = arr[i]; arr[i] = arr[j]; arr[j] = t; }
  function medianOfThree(lo, mid, hi) {
    if (arr[lo] > arr[mid]) swap(lo, mid);
    if (arr[lo] > arr[hi]) swap(lo, hi);
    if (arr[mid] > arr[hi]) swap(mid, hi);
    return mid;
  }
  function partition(lo, hi) {
    const mid = Math.floor((lo + hi) / 2);
    const m = medianOfThree(lo, mid, hi);
    swap(m, hi);
    const pivot = arr[hi];
    let i = lo;
    for (let j = lo; j < hi; j++) {
      if (arr[j] <= pivot) { swap(i, j); i++; }
    }
    swap(i, hi);
    return i;
  }
  function heapSort(lo, hi) {
    const n = hi - lo + 1;
    function heapify(i, size) {
      while (true) {
        const l = 2 * i + 1;
        const r = l + 1;
        let largest = i;
        if (l < size && arr[lo + l] > arr[lo + largest]) largest = l;
        if (r < size && arr[lo + r] > arr[lo + largest]) largest = r;
        if (largest !== i) { swap(lo + i, lo + largest); i = largest; } else break;
      }
    }
    for (let i = Math.floor(n / 2) - 1; i >= 0; i--) heapify(i, n);
    for (let end = n - 1; end > 0; end--) {
      swap(lo, lo + end);
      heapify(0, end);
    }
  }
  function insertionSort(lo, hi) {
    for (let i = lo + 1; i <= hi; i++) {
      const key = arr[i];
      let j = i - 1;
      while (j >= lo && arr[j] > key) { arr[j + 1] = arr[j]; j--; }
      arr[j + 1] = key;
    }
  }
  function quickSort(lo, hi, depth) {
    const size = hi - lo + 1;
    if (size <= 16) { insertionSort(lo, hi); return; }
    if (depth <= 0) { heapSort(lo, hi); return; }
    const p = partition(lo, hi);
    quickSort(lo, p - 1, depth - 1);
    quickSort(p + 1, hi, depth - 1);
  }
  quickSort(0, n - 1, maxDepth);
}
```

## Follow-up Questions
- How would you adapt this to sort objects by a numeric key while preserving comparator locality?
- Compare cache behavior of introsort vs pure mergesort on large datasets.

## Why This Is Asked

This question tests your understanding of counting DP, covering both memoization (top-down) and tabulation (bottom-up) approaches, along with space optimization and edge-case handling.

## Key Concepts

- Subset sum counting with each element used at most once
- Memoization (top-down) with recursive DFS and memo table
- Tabulation (bottom-up) with 1D space optimization to O(S)
- Modulo arithmetic to prevent integer overflow

## Edge Cases

- **Empty subset (N=0)**: If N=0 and S=0, return 1 (one valid subset - empty set). If S>0, return 0.
- **Target S=0**: Always return 1 (the empty subset counts as one valid subset).
- **All elements greater than S**: No valid subsets exist, return 0.

## Code Example

```javascript
function countSubsets(nums, target) {
  const mod = 1_000_000_007;
  const n = nums.length;

  // Top-down with memoization
  const memo = Array.from({ length: n + 1 }, () => Array(target + 1).fill(-1));
  function dfs(i, s) {
    if (s === 0) return 1;
    if (i === 0) return 0;
    if (memo[i][s] !== -1) return memo[i][s];
    memo[i][s] = dfs(i - 1, s) % mod;
    if (s >= nums[i - 1]) {
      memo[i][s] = (memo[i][s] + dfs(i - 1, s - nums[i - 1])) % mod;
    }
    return memo[i][s];
  }
  return dfs(n, target);
}

// Bottom-up with space optimization
function countSubsetsBU(nums, target) {
  const mod = 1_000_000_007;
  const dp = Array(target + 1).fill(0);
  dp[0] = 1;

  for (const num of nums) {
    for (let s = target; s >= num; s--) {
      dp[s] = (dp[s] + dp[s - num]) % mod;
    }
  }
  return dp[target];
}
```

Both solutions run in O(N×S) time with the bottom-up approach using O(S) space.

